'use strict';
// Thirty-two original scenes. Three choices and two bilingual short responses each.
const q=(es,en,a,alternatives,why)=>[es,en,a,alternatives,why];
const s=(title,text,glossary,questions)=>({title,text,glossary,questions});
const units=[
[
s('La foto del barrio','Ana lleva una foto antigua al café de Diego. «Antes vivía en este barrio», dice. «Mi piso era pequeño, pero la cocina tenía una mesa grande. Trabajaba cerca y normalmente iba a pie». Luis mira la foto: «¿Y ese perro?». «Era mi perro. Los domingos iba al parque con él». Ahora Ana vive cerca de la estación y va al trabajo en autobús. La foto no muestra un viaje especial: muestra cómo era su vida antes. Luis quiere ver otra foto del parque.',[['antigua','old'],['normalmente','usually'],['muestra','shows']], [q('¿Qué muestra la foto para Ana?','What does the photo represent for Ana?','Su vida de antes',['Un viaje de mañana','Una compra de ayer'],'Ana explicitly describes former home and routines, not one special trip.'),q('¿Cómo iba al trabajo normalmente?','How did she normally travel to work?','A pie',['On foot','Walking'],'Iba a pie is the old routine; the bus is current.'),q('¿Por qué el piso pequeño servía para comer juntos?','Why could the small flat work for eating together?','La cocina tenía una mesa grande',['No tenía cocina','Estaba en un hotel'],'A large kitchen table supports the simple inference despite the small flat.'),q('¿Dónde iba los domingos?','Where did she go on Sundays?','Al parque',['To the park','The park','Parque'],'Los domingos iba al parque describes repeated visits.'),q('¿Qué pregunta mantiene la conversación sobre el pasado?','Which question continues the conversation about the past?','¿Cómo era el parque?',['¿Cuánto cuesta el billete de hoy?','¿Qué vas a comprar mañana?'],'Cómo era asks for a past description relevant to the next photo.')]),
s('El turno de Diego','Diego prepara café para los amigos. Antes trabajaba por la noche y estudiaba español por la mañana. Tenía poco tiempo para desayunar con otras personas. Ahora trabaja por la mañana y está libre por la tarde. «Antes iba a clase cansado», explica. «Hacía la compra después de estudiar». Marta también estudiaba por la mañana, pero no trabajaba de noche. Los dos comparan sus rutinas. Hoy pueden tomar un café con calma y después ir al parque. Ana pregunta si antes Diego tenía tiempo para leer.',[['turno','work shift'],['con calma','without rushing'],['comparan','compare']], [q('¿Qué ha cambiado en el trabajo de Diego?','What has changed in Diego’s work?','Ahora trabaja por la mañana',['Ahora estudia de noche','Ahora no trabaja'],'The old night shift contrasts with the current morning shift.'),q('¿Cuándo estudiaba Diego?','When did Diego used to study?','Por la mañana',['In the morning','Mornings'],'His study routine was in the morning.'),q('¿Por qué iba cansado a clase?','Why did he go to class tired?','Trabajaba por la noche',['El café estaba lejos','No le gustaba estudiar'],'Night work supports the reason for morning tiredness; no distance is given.'),q('¿Qué hacía después de estudiar?','What did he do after studying?','La compra',['The shopping','Shopping','Hacía la compra'],'Después de estudiar establishes the old routine order.'),q('¿Qué frase de Marta coincide con el texto?','Which statement by Marta matches the text?','Yo también estudiaba por la mañana',['Yo también trabajaba por la noche','Ahora no podemos tomar café'],'Marta shared the study time, not Diego’s night work.')]),
s('El camino a clase','Marta enseña a Luis el camino de su antigua casa a clase. «Vivía al lado de esta tienda. La clase estaba frente al parque. Iba a pie y hablaba con mi hermana por el camino». La tienda sigue aquí, pero ahora Marta vive más lejos y toma el autobús. Luis pregunta por los sábados. Marta explica que no iba a clase: estudiaba en casa y después hacía la compra. Hoy no buscan una clase ni una tienda nueva. Quieren recordar el barrio y tomar algo en el café de la plaza.',[['antigua casa','former home'],['por el camino','on the way'],['recordar','remember']], [q('¿Qué quieren hacer hoy?','What do they want to do today?','Recordar el barrio y tomar algo',['Comprar una casa','Buscar una clase nueva'],'The final lines explicitly exclude a new class or shop search.'),q('¿Dónde estaba la clase?','Where was the class?','Frente al parque',['Opposite the park','In front of the park'],'Frente al parque gives the class location.'),q('¿Por qué toma el autobús ahora?','Why does she take the bus now?','Vive más lejos',['La tienda está cerrada','Tiene clase los sábados'],'The changed home distance explains the transport change.'),q('¿Qué hacía antes de la compra los sábados?','What did she do before shopping on Saturdays?','Estudiaba en casa',['Studied at home','Study at home'],'Estudiaba en casa comes before después hacía la compra.'),q('¿Qué pregunta pide otro recuerdo de la rutina?','Which question asks for another routine memory?','¿Con quién hablabas por el camino?',['¿Dónde cambio de tren mañana?','¿Cuánto cuesta esta casa?'],'Hablabas retrieves the repeated past conversation, not a new purchase.')]),
s('Un parque distinto','Luis y Ana están en el parque. Luis dice: «Cuando era pequeño, el parque era más tranquilo. No había un café y normalmente venía con mi familia». Ana recuerda otra cosa: «Yo iba con mi perro. Tenía una pelota roja y jugábamos al lado de los árboles». Ahora hay un café y muchas personas, pero también un lugar tranquilo detrás de la mesa grande. Los amigos van a sentarse allí. Para ellos, no todo era mejor antes: les gusta poder tomar agua y descansar en el parque de hoy.',[['había','there used to be'],['pelota','ball'],['árboles','trees'],['tranquilo','quiet']], [q('¿Qué cambio mencionan?','Which change do they mention?','Ahora hay un café',['Ahora no hay personas','Ahora el parque no tiene árboles'],'Luis contrasts no former café with one now.'),q('¿Con quién iba Luis?','Who did Luis used to go with?','Con su familia',['With his family','His family'],'His habitual company was his family, not Ana’s dog.'),q('¿Qué piensan del parque actual?','What do they think of the present park?','También tiene cosas buenas',['Todo era mejor antes','Ya no pueden descansar'],'They appreciate water and rest now; the text rejects an all-better-before judgement.'),q('¿Dónde van a sentarse?','Where are they going to sit?','Detrás de la mesa grande',['Behind the large table','Behind the big table'],'The quiet place is behind the large table.'),q('¿Qué respuesta resume el recuerdo de Ana?','Which response summarises Ana’s memory?','Iba al parque con mi perro',['Ayer compré un perro','Mañana voy a comprar una pelota'],'Iba expresses the routine stated in her memory.')])
],
[
s('Una llamada a las seis','Ayer hacía frío y Ana trabajaba en casa. Normalmente comía a las dos, pero ayer tenía mucho trabajo. Luis llamó a las seis para preguntar por la cena. Ana terminó el trabajo y salió al café. Allí comió una sopa y habló con Luis. «Antes trabajaba cerca de este café», dijo. Luis no necesitaba conocer toda su rutina: quería saber si podía cenar con ella esa noche. Al final cenaron juntos. La llamada cambió el plan de Ana, pero no su trabajo habitual.',[['llamó','called'],['terminó','finished'],['esa noche','that night']], [q('¿Qué cambió el plan de Ana?','What changed Ana’s plan?','La llamada de Luis',['Su trabajo habitual','Una compra de ropa'],'The six-o’clock call led to a different dinner plan.'),q('¿Qué hacía Ana cuando llamó Luis?','What was Ana doing when Luis called?','Trabajaba en casa',['Working at home','She was working at home'],'Trabajaba supplies ongoing background to the call.'),q('¿Por qué Luis llamó?','Why did Luis call?','Quería cenar con Ana',['Quería conocer todas sus rutinas','Necesitaba comprar sopa'],'The text contrasts his practical dinner intention with learning her whole routine.'),q('¿Qué hizo Ana después de terminar el trabajo?','What did Ana do after finishing work?','Salió al café',['Went out to the café','Went to the café'],'The finished work precedes her completed outing.'),q('¿Qué frase cuenta un hecho terminado de ayer?','Which statement reports a completed event yesterday?','Comí una sopa en el café',['Normalmente comía a las dos','Antes trabajaba cerca del café'],'Comí advances the completed sequence; the other two describe routines.')]),
s('Dos años en Madrid','Marta vivió en Madrid durante dos años. Ahora vive en Toledo. Ayer visitó el antiguo barrio con Diego. «Cuando vivía aquí, estudiaba español y trabajaba en una tienda», explicó. Diego preguntó por un café pequeño frente a la clase. Marta dijo que normalmente comía allí, pero ayer comieron en la plaza porque el café estaba cerrado. Después fueron a la estación. Diego quiere conocer más sobre la vida de Marta dentro de ese periodo. Marta le enseña la tienda donde trabajaba y le cuenta que antes iba al trabajo a pie. Ahora toma el autobús en Toledo.',[['periodo','period'],['cerrado','closed'],['dentro de','within']], [q('¿Por qué comieron en la plaza?','Why did they eat in the square?','El café estaba cerrado',['Marta nunca iba al café','No tenían tiempo para comer'],'The closed café caused the alternative, despite Marta’s old routine there.'),q('¿Cuánto duró la etapa de Marta en Madrid?','How long did Marta’s Madrid period last?','Dos años',['Two years','2 years'],'Vivió durante dos años treats the stay as a completed whole.'),q('¿Por qué usa vivía al explicar su trabajo?','Why does she use vivía while explaining her work?','Da el fondo de sus rutinas',['Dice que sigue viviendo allí','Cuenta una salida nueva'],'The form frames living there as background inside the completed period.'),q('¿Adónde fueron después de comer?','Where did they go after eating?','A la estación',['To the station','The station'],'Después fueron a la estación follows the square meal.'),q('¿Qué resumen respeta las dos formas de contar el pasado?','Which summary respects both past perspectives?','Viví dos años en Madrid. Allí estudiaba español',['Vivo dos años allí ayer','Estudiaba español mañana'],'A bounded stay and an internal routine can coexist; duration is not a mechanical tense rule.')]),
s('Antes de la lluvia','El sábado hacía buen tiempo. Luis y Marta estaban en el café y querían caminar hasta el parque. Primero comieron y después salieron. Cuando llegaron a la plaza, empezó a llover. Volvieron al café y tomaron té. No fue el paseo largo que querían, pero hablaron de sus viajes y estuvieron juntos. Ahora Luis escribe a Ana: «Comimos antes de salir. Después llovió y volvimos al café». Ana entiende el orden sin pensar que el buen tiempo continuó toda la tarde.',[['empezó a llover','started raining'],['volvieron','returned'],['continuó','continued']], [q('¿Qué causó la vuelta al café?','What caused the return to the café?','Empezó a llover',['No había comida','Ana llamó'],'The weather changed at the square, leading to the return.'),q('¿Dónde estaban al principio?','Where were they at the start?','En el café',['At the café','The café'],'Estaban provides the initial location before the outing.'),q('¿Por qué Ana puede entender el cambio?','Why can Ana understand the change?','El mensaje cuenta las acciones en orden',['El mensaje dice que hizo sol toda la tarde','El mensaje no menciona la lluvia'],'Antes/después and the event sequence clarify that the weather changed.'),q('¿Qué hicieron antes de salir?','What did they do before going out?','Comieron',['They ate','Ate','Comer'],'The meal precedes the completed exit.'),q('¿Qué frase describe el fondo al principio?','Which statement describes the initial background?','Hacía buen tiempo',['Empezó a llover','Volvimos al café'],'Hacía sets the initial scene; the other statements are events.')]),
s('La mesa de siempre','Diego trabajaba en el café ayer por la tarde. Una familia entró y pidió cuatro cafés. Diego preparó los cafés y buscó una mesa. La mesa grande estaba ocupada, así que la familia se sentó junto a la ventana. Luis llegó después y comió con Diego cuando terminó el trabajo. Antes Luis comía allí casi todos los días; ahora solo va los sábados. Ayer fue una excepción porque estaba cerca. Diego no cambia los precios para sus amigos: Luis pagó como todas las otras personas.',[['ocupada','occupied'],['ventana','window'],['excepción','exception']], [q('¿Dónde se sentó la familia?','Where did the family sit?','Junto a la ventana',['En la mesa grande','Fuera del café'],'The occupied large table forced the window alternative.'),q('¿Cuántos cafés pidió?','How many coffees did the family order?','Cuatro',['Four','4'],'Four is the order quantity, not the number of regular visits.'),q('¿Por qué fue Luis un día distinto del sábado?','Why did Luis visit on a day other than Saturday?','Estaba cerca',['No tenía que pagar','Iba todos los días ahora'],'Current visits are Saturdays; proximity explains the exception.'),q('¿Qué hizo Luis después de comer?','What did Luis do after eating?','Pagó',['He paid','Paid','Pagar'],'The final sentence reports paying the normal price.'),q('¿Qué frase cuenta la antigua rutina de Luis?','Which statement describes Luis’s old routine?','Comía allí casi todos los días',['Ayer comí con Diego','Hoy pago cuatro cafés'],'Comía and casi todos los días frame the repeated earlier action.')])
],
[
s('El andén nuevo','Ana y Luis llegan a la estación a las nueve. Antes el tren a Toledo salía del andén dos, pero hoy sale del cuatro. Ana mira el billete y Luis pregunta a una trabajadora. «Sigan recto hasta la escalera y después a la izquierda», responde. La trabajadora repite despacio porque Luis no entiende la segunda parte. Llegan al andén cuatro antes de la salida. Ana escribe a Marta para avisar: no deben esperar en el lugar de siempre. El cambio de andén no significa que el tren vaya a otra ciudad.',[['andén','platform'],['escalera','stairs'],['avisar','let someone know'],['sigan','go/continue (staff instruction)']], [q('¿Qué cambió hoy?','What changed today?','El andén de salida',['La ciudad de destino','El precio del café'],'Departure platform changed, not destination.'),q('¿De qué andén sale hoy?','Which platform does it leave from today?','Del cuatro',['Platform four','4','Del andén cuatro'],'The current departure is four; two is the old arrangement.'),q('¿Por qué pide Luis otra explicación?','Why does Luis ask for another explanation?','No entiende la segunda parte',['No quiere ir a Toledo','Ha perdido el billete'],'He needs clarification of directions, not a different trip.'),q('¿Qué deben hacer después de la escalera?','What must they do after the stairs?','Ir a la izquierda',['Go left','Turn left','A la izquierda'],'Después links the left turn to the stairs.'),q('¿Qué mensaje ayuda a Marta?','Which message helps Marta?','Hoy el tren sale del andén cuatro',['El tren va a otra ciudad','No hay trenes hoy'],'The useful message communicates the changed platform accurately.')]),
s('Un autobús en lugar del tren','Ayer Luis perdió el tren porque llegó tarde a la estación. El siguiente tren salía dos horas después. Luis tenía una cita con Marta, así que preguntó por un autobús. Tuvo que comprar otro billete, pero pudo llegar antes de la cita. Marta estaba esperando en el café y no sabía lo del tren. Luis explicó el problema antes de pedir comida. Ahora guarda el nuevo billete junto al viejo. No quiere recordar solo el error: también quiere recordar la solución que encontró.',[['siguiente','next'],['guarda','keeps'],['solución','solution']], [q('¿Qué solución encontró Luis?','What solution did Luis find?','Tomar un autobús',['Esperar dos horas por el tren','Cancelar toda la cita'],'The bus let him arrive before the appointment.'),q('¿Por qué perdió el tren?','Why did he miss the train?','Llegó tarde',['He arrived late','Arrived late'],'Llegó tarde causes the completed missed train.'),q('¿Por qué no esperó el siguiente tren?','Why did he not wait for the next train?','Tenía una cita y tardaba dos horas',['No tenía ningún billete','Marta estaba en el tren'],'The appointment and long wait explain the alternative.'),q('¿Qué hizo antes de pedir comida?','What did he do before ordering food?','Explicó el problema',['Explained the problem','Told Marta what happened'],'He explains the travel problem first.'),q('¿Qué frase distingue fondo y hecho?','Which statement distinguishes background and event?','Tenía una cita y perdí el tren',['Tengo una cita ayer y perder el tren','Voy a perder el tren ayer'],'Tenía supplies the appointment situation; perdí names the event.')]),
s('Una conexión con tiempo','Marta viajó ayer a un pueblo cerca de Toledo. Tuvo que cambiar de autobús en la estación. La primera parada estaba frente al café, pero la segunda quedaba detrás de la plaza. Un trabajador explicó el camino: recto hasta la plaza y después a la derecha. Marta llegó a tiempo porque había veinte minutos entre los autobuses. Antes pensaba que cambiar era difícil. Ahora sabe que puede preguntar y repetir la información para comprobarla. Hoy cuenta el viaje a Diego y guarda el horario para otra visita.',[['parada','stop'],['horario','timetable'],['comprobarla','check it']], [q('¿Qué ayudó a Marta a llegar a tiempo?','What helped Marta arrive in time?','Tenía veinte minutos para cambiar',['Los autobuses salían del mismo sitio','No tuvo que cambiar'],'The available transfer time and directions supported the connection.'),q('¿Dónde estaba la segunda parada?','Where was the second stop?','Detrás de la plaza',['Behind the square','Behind the plaza'],'The second stop contrasts with the first café-front location.'),q('¿Qué aprendió para otros viajes?','What did she learn for future journeys?','Puede preguntar y comprobar la información',['Nunca debe preguntar','Todos los autobuses tienen la misma parada'],'Clarifying and repeating information are the practical strategy.'),q('¿Hacia dónde giró después de la plaza?','Which way did she turn after the square?','A la derecha',['Right','To the right','Turned right'],'The staff directions place the right turn after the square.'),q('¿Qué pregunta sirve en un viaje parecido?','Which question suits a similar journey?','¿Dónde tengo que cambiar?',['¿La sopa lleva carne?','¿Tiene otra talla?'],'The question asks for the necessary transport transfer.')]),
s('El tren parado','El tren estaba parado cuando Ana llegó al andén. Una persona explicó que había un problema y que no podían salir todavía. Ana no sabía cuánto iba a durar la espera. Preguntó en la estación y llamó a Luis. «No pude salir a las nueve. Voy a llegar más tarde», dijo. Luis propuso tomar el autobús, pero Ana prefirió esperar: no tenía otra cita y su billete seguía siendo válido. Al final el tren salió a las diez. Ana avisó a Marta de la nueva hora.',[['espera','wait'],['válido','valid'],['avisó','informed'],['seguía siendo','was still']], [q('¿Por qué decidió esperar Ana?','Why did Ana decide to wait?','No tenía otra cita y su billete servía',['El autobús no existía','Luis estaba en el tren'],'Her circumstances made waiting reasonable; no missing bus is stated.'),q('¿A qué hora salió el tren al final?','What time did the train finally leave?','A las diez',['At ten','Ten','10'],'Ten is the eventual departure, not the intended nine.'),q('¿Qué informa no pude salir a las nueve?','What does no pude salir a las nueve communicate?','La salida no fue posible a esa hora',['Ana nunca podía viajar','Ana salió a las nueve'],'The statement reports a particular unsuccessful departure.'),q('¿A quién llamó antes de decidir?','Who did she call before deciding?','A Luis',['Luis','She called Luis'],'Luis proposed the bus before Ana chose to wait.'),q('¿Qué mensaje encaja con la solución final?','Which message fits the final solution?','El tren salió a las diez; voy a llegar más tarde',['Tomé el autobús a las nueve','Nunca hubo un problema'],'It reports the actual later train departure without inventing a bus journey.')])
],
[
s('Una mesa para cuatro','Ana, Luis, Marta y Diego entran en un restaurante cerca del parque. Quieren comer juntos, pero Marta no come carne. Antes siempre pedían la misma sopa. Hoy Marta pregunta si lleva carne y el camarero dice que sí, lleva pollo. Ella pide una ensalada sin carne. Los otros piden sopa y el grupo comparte dos botellas de agua. Luis quiere comparar los platos, no cambiar la elección de Marta. Todos tienen comida que les gusta. Después van a pedir café, pero todavía no quieren la cuenta.',[['pollo','chicken'],['comparte','shares'],['platos','dishes']], [q('¿Por qué Marta cambia la sopa por ensalada?','Why does Marta choose salad instead of soup?','La sopa lleva carne',['La ensalada es más grande','No tiene hambre'],'Her meat preference and the ingredient answer explain the change.'),q('¿Cuántas botellas de agua comparte el grupo?','How many bottles of water does the group share?','Dos',['Two','2'],'The shared quantity is two bottles.'),q('¿Qué significa el cambio de pedido?','What does the changed order mean?','Marta puede respetar su preferencia',['Todos deben pedir ensalada','Luis decide por Marta'],'A useful ingredient question lets her choose appropriately; she does not dictate others’ food.'),q('¿Qué van a pedir antes de la cuenta?','What will they order before the bill?','Café',['Coffee','Coffees'],'Coffee is planned before paying.'),q('¿Qué pregunta ayudó a elegir?','Which question helped choose?','¿La sopa lleva carne?',['¿De qué andén sale?','¿A qué hora cambias de tren?'],'The ingredient question is directly relevant to the preference.')]),
s('Falta un café','Después de comer, Luis pidió dos cafés para él y Ana. El camarero trajo uno y dejó la cuenta en la mesa. Ana explicó: «Pedimos dos cafés, pero falta uno». El camarero miró la mesa y dijo que iba a traer el otro. Luis no necesitó hablar más alto ni repetir todo el pedido. Esperaron unos minutos y recibieron el segundo café. Después pagaron con tarjeta. Ana piensa que explicar el problema concreto con amabilidad fue más útil que decir solo que todo estaba mal.',[['trajo','brought'],['pedido','order'],['recibieron','received']], [q('¿Qué problema explicaron?','What problem did they explain?','Faltaba uno de los dos cafés',['No tenían tarjeta','La comida estaba fría'],'The issue was one missing coffee, not the entire meal.'),q('¿Cómo pagaron?','How did they pay?','Con tarjeta',['By card','With a card'],'They paid by card after receiving the second coffee.'),q('¿Por qué sirvió la explicación de Ana?','Why did Ana’s explanation help?','Identificó el problema concreto',['Habló más alto','Cambió toda la comida'],'A specific polite description helped the waiter act.'),q('¿Qué recibieron antes de pagar?','What did they receive before paying?','El segundo café',['The second coffee','Another coffee'],'Receiving the missing coffee precedes payment.'),q('¿Qué frase resuelve una situación igual?','Which statement helps in the same situation?','Pedí dos cafés y falta uno',['El café era tranquilo antes','Quiero cuatro billetes'],'It links the completed order to the present missing item.')]),
s('La sopa equivocada','Marta pidió una sopa sin carne y una botella de agua. Cuando llegó la sopa, tenía pollo. Marta no empezó a comer. Llamó al camarero y explicó el problema: «Pedí una sopa sin carne, pero esta tiene carne». Él pidió disculpas y ofreció una ensalada. Marta aceptó porque tenía poco tiempo y la ensalada no llevaba carne. Antes comía sopa casi todos los días; hoy lo importante era tener una opción adecuada. Luis esperó con ella y después los dos fueron a la estación.',[['equivocada','wrong'],['ofreció','offered'],['adecuada','suitable']], [q('¿Qué eligió Marta como solución?','What did Marta choose as the solution?','Una ensalada sin carne',['La misma sopa','Salir sin comer'],'She accepted the meat-free salad, not the incorrect soup.'),q('¿Qué ingrediente tenía la sopa?','Which ingredient was in the soup?','Pollo',['Chicken'],'The actual soup contained chicken despite the meat-free request.'),q('¿Por qué aceptó la ensalada?','Why did she accept the salad?','No llevaba carne y tenía poco tiempo',['No le gustaba nunca la sopa','Era su pedido original'],'Both dietary suitability and limited time support her choice.'),q('¿Adónde fueron después?','Where did they go afterwards?','A la estación',['To the station','The station'],'The meal is followed by the station trip.'),q('¿Qué frase distingue rutina y pedido de hoy?','Which statement distinguishes routine and today’s order?','Antes comía sopa, pero hoy pedí una ensalada',['Antes comí siempre mañana','Hoy siempre comía antes'],'Imperfect gives the old habit; pedí presents today’s specific order.')]),
s('Una cuenta para comprobar','Diego y Ana comen en un café nuevo. La comida es buena y el lugar es más tranquilo que el de la estación. Piden la cuenta y ven tres cafés, aunque solo tomaron dos. Diego pregunta con calma: «Tomamos dos cafés. ¿Puede comprobar la cuenta, por favor?». La camarera revisa el pedido y cambia el total. Ana no quiere pagar menos de lo que comieron; quiere pagar lo correcto. Después decide volver otro día porque le gusta el café y el problema tuvo una solución sencilla.',[['comprobar','check'],['revisa','checks'],['total','total']], [q('¿Qué quieren corregir?','What do they want corrected?','La cuenta incluye un café de más',['La comida no llegó','La tarjeta no funciona'],'Three coffees appear, but only two were taken.'),q('¿Cuántos cafés tomaron?','How many coffees did they have?','Dos',['Two','2'],'Two is the actual quantity, distinguished from the bill’s three.'),q('¿Por qué Ana quiere volver?','Why does Ana want to return?','Le gusta el café y resolvieron el problema',['Quiere pagar siempre menos','No comprobaron la cuenta'],'The good experience and successful correction explain returning.'),q('¿Qué cambió la camarera?','What did the waitress change?','El total de la cuenta',['The bill total','The total'],'She adjusts the total after reviewing the order.'),q('¿Qué petición es adecuada?','Which request is suitable?','¿Puede comprobar la cuenta, por favor?',['¿Puede traer una talla más grande?','¿De qué andén sale el café?'],'The request addresses the bill discrepancy politely.')])
],
[
s('La camiseta mediana','Ana vuelve a la tienda con una camiseta azul. Ayer la compró, pero en casa vio que le quedaba pequeña. Tiene el recibo y no quiere otro color: quiere la talla mediana. El dependiente mira el recibo y busca la misma camiseta. Hay una mediana, pero cuesta lo mismo que la pequeña. Ana se la prueba y le queda bien. Antes compraba ropa sin probarla; ahora prefiere comprobar la talla en la tienda. Luis espera fuera y después los dos van a tomar un café.',[['recibo','receipt'],['se la prueba','tries it on'],['comprobar','check']], [q('¿Qué quiere cambiar Ana?','What does Ana want to change?','La talla, no el color',['El color y el precio','La tienda'],'She wants medium in the same blue T-shirt.'),q('¿Qué trae para explicar la compra?','What does she bring as proof of purchase?','El recibo',['The receipt','A receipt'],'The assistant checks the receipt.'),q('¿Qué cambió en su manera de comprar?','What changed in her shopping approach?','Ahora prefiere probar la ropa',['Ahora nunca compra ropa','Ahora compra sin recibo'],'Her former habit lacked trying on; now she checks size.'),q('¿Qué hace antes de aceptar la mediana?','What does she do before accepting medium?','Se la prueba',['Tries it on','Tries on the T-shirt'],'Trying it confirms the fit before the café visit.'),q('¿Qué frase explica el problema inicial?','Which statement explains the original problem?','La camiseta me queda pequeña',['El móvil no funciona','No hay agua caliente'],'This is a clothing-fit problem, not a faulty phone or hotel issue.')]),
s('El móvil con recibo','Luis compró un móvil la semana pasada. Funcionaba bien, pero ayer dejó de funcionar. Hoy vuelve a la tienda con el móvil y el recibo. «No funciona. ¿Puede ayudarme?», pregunta. La dependienta comprueba el móvil y explica que puede cambiarlo por otro igual. Luis no necesita un modelo más caro ni otro color. Necesita un móvil que funcione para llamar a su familia. Acepta el cambio y comprueba el nuevo antes de salir. Después llama a Marta para decir que ya puede recibir llamadas.',[['dejó de funcionar','stopped working'],['igual','the same kind'],['recibir llamadas','receive calls']], [q('¿Qué necesita Luis realmente?','What does Luis actually need?','Un móvil que funcione',['El modelo más caro','Un color nuevo'],'His practical need is calling family, not upgrading.'),q('¿Cuándo dejó de funcionar?','When did it stop working?','Ayer',['Yesterday'],'Yesterday’s failure contrasts with its earlier working condition.'),q('¿Por qué comprueba el nuevo móvil?','Why does he check the new phone?','Para comprobar que el problema está resuelto',['Para cambiar el color','Para perder el recibo'],'Testing the replacement verifies the solution before leaving.'),q('¿A quién llama después del cambio?','Who does he call after the exchange?','A Marta',['Marta','He calls Marta'],'The last message lets Marta know calls work again.'),q('¿Qué petición ayuda en la tienda?','Which request helps at the shop?','Tengo el recibo. ¿Puede ayudarme?',['No quiero ningún móvil que funcione','Quiero la cuenta del café'],'The receipt plus a polite help request supports the service exchange.')]),
s('La bolsa rota','Marta fue ayer a comprar una bolsa para el viaje. Quería una pequeña y vio dos opciones: una costaba diez euros y la otra doce. La más barata estaba rota. No quiso comprarla, aunque costaba menos. La dependienta buscó otra bolsa del mismo tamaño y precio. Marta la miró bien y la compró. Hoy explica a Diego que comparar precios no era suficiente: también necesitaba comprobar el estado. No quiere una bolsa especial. Quiere llevar la ropa sin perder nada durante el viaje.',[['rota','broken'],['estado','condition'],['tamaño','size']], [q('¿Por qué rechazó la primera bolsa barata?','Why did she reject the first cheap bag?','Estaba rota',['Era demasiado grande','Costaba doce euros'],'Its condition, not size or higher price, caused the refusal.'),q('¿Cuánto costaba la opción más barata?','What did the cheaper option cost?','Diez euros',['Ten euros','10 euros'],'The two prices were ten and twelve; ten is cheaper.'),q('¿Qué enseña la comparación de Marta?','What does Marta’s comparison show?','El precio y el estado importan',['Solo importa el precio','Todas las bolsas eran especiales'],'A lower price did not compensate for the broken bag.'),q('¿Qué hizo antes de comprar la segunda?','What did she do before buying the second bag?','La miró bien',['Checked it carefully','Looked at it carefully'],'Inspecting the alternative precedes the purchase.'),q('¿Qué frase cuenta su decisión?','Which sentence reports her decision?','No quise comprarla porque estaba rota',['No quiero comprarla mañana porque era nueva','No querer compra ayer'],'No quise presents the particular refusal; estaba explains it.')]),
s('Dos chaquetas','Ana y Luis comparan dos chaquetas. La roja es más barata, pero la azul le queda mejor a Luis. Ayer vino a cambiar una chaqueta que era demasiado grande. Hoy trae el recibo y quiere elegir con tiempo. La dependienta explica que la azul cuesta cinco euros más. Luis se prueba las dos y decide pagar la diferencia. Ana está de acuerdo: no necesita la prenda más barata si no le queda bien. Antes Luis elegía siempre por el precio; esta vez también mira la talla y la comodidad.',[['diferencia','difference'],['comodidad','comfort'],['elegía','used to choose']], [q('¿Qué chaqueta elige Luis?','Which jacket does Luis choose?','La azul',['La roja','La de ayer'],'The blue fits better, and he accepts its higher price.'),q('¿Cuánto más cuesta?','How much more does it cost?','Cinco euros',['Five euros','5 euros'],'The blue adds five euros, not the entire jacket price.'),q('¿Por qué acepta pagar más?','Why does he accept paying more?','Le queda mejor',['No tiene recibo','Nunca mira la talla'],'Fit matters alongside price.'),q('¿Qué hizo ayer?','What did he do yesterday?','Vino a cambiar una chaqueta',['Came to exchange a jacket','Exchanged a jacket'],'The prior visit was to exchange the oversized jacket.'),q('¿Qué frase compara las opciones con precisión?','Which comparison is accurate?','La roja es más barata, pero la azul me queda mejor',['La azul es más barata y más grande','Las dos cuestan lo mismo'],'It preserves the price/fit trade-off instead of reversing it.')])
],
[
s('La hora nueva','Ana iba a quedar con Luis a las siete. Perdió el autobús porque salió tarde del trabajo. Escribe: «Voy a llegar a las ocho. ¿Podemos quedar a las ocho y media?». Luis está libre y acepta la nueva hora. Marta no puede tan tarde porque tiene que trabajar por la noche. Ana no quiere olvidar a Marta, así que propone otro café con ella mañana. El plan de hoy cambia, pero no todos tienen la misma disponibilidad. Ana explica el problema y ofrece una alternativa sin decir que nadie quiere verla.',[['disponibilidad','availability'],['ofrece','offers'],['tan tarde','so late']], [q('¿Qué hora acepta Luis?','Which time does Luis accept?','Las ocho y media',['Las siete','Las ocho'],'Eight is Ana’s arrival; half past eight is the meeting.'),q('¿Por qué no puede Marta?','Why can Marta not join?','Tiene que trabajar por la noche',['She has to work at night','Work at night'],'Her night work conflicts with the later time.'),q('¿Por qué propone Ana un café mañana?','Why does Ana propose coffee tomorrow?','Quiere incluir a Marta en otro plan',['Luis rechaza el plan de hoy','Marta no quiere verla'],'A separate plan accommodates Marta’s schedule without assuming rejection.'),q('¿Qué perdió Ana antes del mensaje?','What did Ana miss before sending the message?','El autobús',['The bus','Bus'],'The missed bus is the cause of the time change.'),q('¿Qué respuesta confirma el plan con Luis?','Which response confirms the plan with Luis?','De acuerdo, quedamos a las ocho y media',['Nos vemos a las siete como antes','No puedo venir ayer'],'It confirms the revised shared meeting time.')]),
s('Una tarde de trabajo','Ayer Diego no pudo ir al parque porque trabajaba en el café. Ana y Marta fueron, pero decidieron repetir el paseo con él otro día. Hoy Diego está libre por la tarde. Propone las cinco, aunque Marta sale del trabajo a las seis. Al final quedan a las seis y media delante del café. No necesitan cambiar de lugar: solo de hora. Diego va a llevar agua y Ana va a llevar algo de comer. Primero van a caminar un poco y después van a comer.',[['repetir','do again'],['algo de comer','something to eat'],['por la tarde','in the afternoon']], [q('¿Qué parte del plan cambian?','Which part of the plan changes?','La hora',['El lugar','La bebida'],'The café remains the meeting place; the time moves later.'),q('¿A qué hora quedan al final?','What time do they finally meet?','A las seis y media',['At half past six','Six thirty','6:30'],'Marta’s six-o’clock finish leads to a six-thirty meeting.'),q('¿Por qué no sirve la primera propuesta?','Why does the first proposal not work?','Marta todavía trabaja a las cinco',['Diego trabaja toda la tarde hoy','Ana no tiene agua'],'Five is before Marta finishes; Diego is free today.'),q('¿Quién va a llevar agua?','Who will bring water?','Diego',['Diego will'],'Diego brings water, Ana food.'),q('¿Qué mensaje usa planes ya conocidos?','Which message uses familiar plan language?','Vamos a caminar y después vamos a comer',['Comemos ayer después de mañana','Fuimos al parque mañana'],'Ir a sequences the future activities without needing a new future paradigm.')]),
s('La espera terminó','Luis estuvo en la estación hasta las nueve porque su tren llegó tarde. Mientras esperaba, escribió a Ana: «No puedo llegar a las ocho. ¿Qué tal a las diez?». Ana aceptó, pero cambió el restaurante por el café de Diego porque estaba más cerca. Cuando Luis llegó, explicó que pudo leer, aunque estaba cansado. Ana no necesitaba más detalles del retraso. Quería saber si Luis prefería comer o descansar. Luis eligió una sopa y después volver a casa. No cancelaron el encuentro; lo hicieron más sencillo.',[['mientras','while'],['retraso','delay'],['encuentro','meeting']], [q('¿Cómo adaptaron el encuentro?','How did they adapt the meeting?','Más tarde y en un café cercano',['Lo cancelaron','Fueron a la estación juntos'],'They adjusted time and proximity rather than cancelling.'),q('¿Hasta qué hora estuvo Luis en la estación?','Until what time was Luis at the station?','Hasta las nueve',['Until nine','Nine'],'Estuvo bounds the completed waiting period.'),q('¿Por qué Ana pregunta por comer o descansar?','Why does Ana ask about food or rest?','Luis está cansado después de la espera',['Quiere todos los detalles del tren','No existe ningún café'],'His current tiredness makes the practical choice useful.'),q('¿Qué eligió hacer después de la sopa?','What did he choose after soup?','Volver a casa',['Go home','Return home'],'The stated sequence ends with home rather than another outing.'),q('¿Qué frase cuenta la espera como periodo terminado?','Which statement presents the wait as a finished period?','Estuve en la estación hasta las nueve',['Estaba esperando cuando escribí','Estoy en la estación mañana'],'Estuve packages the completed stay; estaba frames an ongoing moment.')]),
s('Sábado, no domingo','Marta propone ir al cine el domingo. Luis responde que no puede porque tiene una visita familiar. Ana prefiere el sábado y Diego está de acuerdo. Marta tampoco puede el sábado por la mañana, pero está libre por la tarde. Cambian el plan al sábado a las seis. Luis explica que antes iba al cine los domingos con su familia; esta semana quiere verlos en casa. Luis confirma el sábado: «¿Podéis venir a las seis?». Todos pueden. Marta va a comprar los billetes antes de quedar, así que nadie tiene que esperar en la puerta del cine.',[['visita familiar','family visit'],['confirma','confirms'],['esperar','wait']], [q('¿Qué plan acuerdan?','Which plan do they agree on?','El sábado a las seis',['El domingo por la mañana','El sábado por la mañana'],'Saturday afternoon at six meets the actual availability.'),q('¿Por qué no puede Luis el domingo?','Why is Luis unavailable Sunday?','Tiene una visita familiar',['A family visit','He has a family visit'],'The family visit is the conflict, not dislike of cinema.'),q('¿Qué diferencia importante explica Luis?','Which important difference does Luis explain?','Su rutina antigua no es su plan de esta semana',['No le gusta nunca el cine','El domingo siempre es imposible'],'Former Sunday cinema habits do not dictate this week’s family arrangement.'),q('¿Quién apoya la propuesta de Ana?','Who supports Ana’s proposal?','Diego',['Diego does'],'Diego agrees with Saturday before the final time is set.'),q('¿Qué pregunta comprueba la nueva hora?','Which question checks the new time?','¿Podéis venir el sábado a las seis?',['¿Fuisteis ayer el domingo?','¿Cuántas tallas hay?'],'Podéis asks the group about the new arrangement.')])
],
[
s('El tren y el precio','Ana prefiere el tren para ir a Toledo porque es más rápido. Marta piensa que el autobús es mejor para ellas hoy: cuesta menos y tienen toda la mañana libre. Luis está de acuerdo con la comparación del precio, pero no con la elección. Tiene poco tiempo y va a tomar el tren. Nadie necesita cambiar la opinión de los otros. Ana decide viajar con Luis y Marta va en autobús con Diego. Quedan todos en la misma plaza a las doce. Una diferencia de opinión no impide un plan común.',[['opinión','opinion'],['elección','choice'],['impide','prevents']], [q('¿Qué permite mantener el plan común?','What keeps the shared plan possible?','Quedar en la misma plaza',['Tomar todos el mismo transporte','Cambiar todas las opiniones'],'Different transport choices still share the place/time.'),q('¿A qué hora quedan?','What time do they meet?','A las doce',['At twelve','Noon','12'],'The shared meeting is twelve.'),q('¿Por qué elige Luis el tren?','Why does Luis choose the train?','Tiene poco tiempo',['Es más barato','Marta cambia de opinión'],'He prioritises speed despite agreeing about the bus price.'),q('¿Con quién viaja Marta?','Who does Marta travel with?','Con Diego',['With Diego','Diego'],'Marta and Diego take the bus.'),q('¿Qué frase reconoce una ventaja y mantiene otra preferencia?','Which statement recognises an advantage but keeps another preference?','El autobús cuesta menos, pero prefiero el tren',['El autobús es más caro y más rápido','Todos deben pensar igual'],'Pero allows agreement on price and a different preference.')]),
s('Una película larga','Luis y Ana vieron una película ayer. La película era larga, pero a Ana le gustó porque la música era buena. Luis también disfrutó de la música, aunque no le gustó el final. Hoy Marta pregunta si merece la pena verla. Ana dice: «Para mí, es una buena película». Luis añade: «Estoy de acuerdo sobre la música, pero el final no me parece bueno». Marta puede elegir con dos opiniones diferentes. Marta quiere valorar las dos opiniones antes de comprar el billete. Le interesa mucho la música, así que va a verla el sábado con Diego. Después van a hablar con Ana y Luis sobre el final.',[['final','ending'],['merece la pena','is worth it'],['valorar','judge/appreciate']], [q('¿En qué coinciden Ana y Luis?','What do Ana and Luis agree about?','La música era buena',['El final les gustó a los dos','Era una película corta'],'Both appreciated the music; Luis disliked the ending.'),q('¿Qué no le gustó a Luis?','What did Luis dislike?','El final',['The ending','Ending'],'The ending, not the music, is his reservation.'),q('¿Por qué sirven las dos opiniones a Marta?','Why are both opinions useful to Marta?','Puede elegir según lo que le importa',['Una opinión tiene que ser falsa','No puede ver la película'],'Different preferences inform a choice without requiring one false opinion.'),q('¿Cuándo vieron la película?','When did they see the film?','Ayer',['Yesterday'],'Ayer locates the completed viewing.'),q('¿Qué respuesta da una opinión con una razón?','Which response gives an opinion and a reason?','Me gustó porque la música era buena',['Vi la película ayer','La película estaba en el cine'],'Porque adds the stated reason for liking it.')]),
s('También y tampoco','Marta no quiere comer carne hoy. Ana tampoco quiere, pero Luis sí. En el restaurante pueden pedir platos distintos y sentarse juntos. Diego piensa que una ensalada es una buena opción; Marta también piensa eso. Luis pregunta si la sopa lleva pollo antes de pedirla. El camarero pregunta por el resto del pedido. Marta dice: «Una ensalada y agua, por favor». Ana pide lo mismo y Diego elige una sopa sin carne. Después todos van al café, porque los cuatro quieren tomar algo y hablar del viaje. Las diferencias de comida no cambian esa idea.',[['platos distintos','different dishes'],['resto del pedido','rest of the order'],['lo mismo','the same']], [q('¿Qué no cambia por las preferencias de comida?','What remains unchanged despite food preferences?','El plan de tomar algo juntos después',['Todos piden carne','Nadie va al restaurante'],'They can differ in food and keep the café plan.'),q('¿Quién tampoco quiere carne?','Who also does not want meat?','Ana',['Ana does not','Ana tampoco'],'Tampoco connects Ana’s negative preference to Marta’s.'),q('¿Qué significa también en la opinión de Marta?','What does también add to Marta’s opinion?','Comparte la opinión positiva de Diego',['Rechaza la ensalada','No quiere sentarse'],'También joins the affirmative salad preference.'),q('¿Qué comprueba Luis antes de pedir sopa?','What does Luis check before ordering soup?','Si lleva pollo',['Whether it contains chicken','The chicken ingredient'],'He asks about ingredients before ordering.'),q('¿Qué respuesta sigue una preferencia negativa compartida?','Which reply follows a shared negative preference?','A mí tampoco',['A mí también me gusta mucho','Estoy más barato'],'Tampoco connects negatives, unlike también in an affirmative preference.')]),
s('El café tranquilo','Diego quiere llevar a los amigos a un café nuevo. Para él, es más tranquilo y la comida es buena. Marta cree que el café de la estación es mejor para hoy porque está más cerca. Ana no está de acuerdo: tienen tiempo y prefiere caminar un poco. Luis propone mirar el horario antes de decidir. El café nuevo cierra a las cinco y son las cuatro y media. Al final eligen el de la estación. No cambia su opinión sobre la tranquilidad; cambian la decisión por una razón práctica.',[['horario','opening hours'],['cierra','closes'],['decisión','decision']], [q('¿Por qué eligen el café de la estación?','Why do they choose the station café?','El nuevo cierra pronto',['El nuevo es más ruidoso según todos','Ana no quiere caminar nunca'],'Closing time changes the practical decision without changing the quietness judgement.'),q('¿A qué hora cierra el nuevo café?','When does the new café close?','A las cinco',['At five','Five','5'],'Five leaves only half an hour at their current time.'),q('¿Qué demuestra el cambio final?','What does the final change show?','Una opinión y una decisión práctica pueden ser distintas',['Todos piensan que el nuevo es malo','Nadie miró el horario'],'They retain their quality opinion but choose the feasible option.'),q('¿Quién propone mirar el horario?','Who suggests checking the opening hours?','Luis',['Luis does'],'Luis supplies the practical check.'),q('¿Qué mensaje da la razón de la decisión?','Which message gives the reason for the decision?','Vamos al de la estación porque el otro cierra pronto',['El nuevo era tranquilo antes','No quiero hablar de cafés'],'Porque links choice to its supported practical reason.')])
],
[
s('La mañana del viaje','Ana iba a viajar a Toledo con Luis. Hacía frío y el autobús de su barrio estaba parado. Ana esperó unos minutos, pero perdió el tren de las nueve. Llamó a Luis y explicó el problema. Luis ya estaba en la estación y preguntó por otra opción. Había un tren a las diez, pero Ana podía tomar un autobús directo. Eligió el autobús porque costaba menos y llegaba antes de las once. Luis tomó el tren de las diez. Quedaron delante del museo: la mañana cambió, pero el plan de verse siguió adelante.',[['directo','direct'],['opción','option'],['siguió adelante','went ahead']], [q('¿Cómo pudieron mantener el encuentro?','How did they keep the meeting possible?','Tomaron opciones distintas y quedaron en el museo',['Cancelaron el museo','Ana tomó el tren de las nueve'],'Alternative transport still led to the same meeting place.'),q('¿Qué tren perdió Ana?','Which train did Ana miss?','El de las nueve',['The nine-o’clock train','The train at nine'],'The missed train is nine; Luis later takes ten.'),q('¿Por qué eligió el autobús directo?','Why did Ana choose the direct bus?','Costaba menos y llegaba antes de las once',['No existía otro tren','Luis iba en ese autobús'],'Both price and arrival make the choice sensible.'),q('¿Dónde quedaron al final?','Where did they arrange to meet?','Delante del museo',['In front of the museum','Outside the museum'],'The agreed meeting point survives the transport change.'),q('¿Qué frase distingue fondo y problema?','Which statement distinguishes background and problem?','El autobús estaba parado y perdí el tren',['El autobús está parado ayer y perder el tren','Voy al museo ayer'],'Estaba frames the condition; perdí identifies the completed missed connection.')]),
s('La comida y la cuenta','Ana llegó al museo antes de Luis y esperó dentro porque hacía frío. Visitaron dos salas y después fueron a comer con Marta. Ana pidió una sopa sin carne, pero la primera sopa llevaba pollo. Explicó el problema y eligió una ensalada. Luis pidió dos cafés para ellos, pero solo llegó uno. Marta pidió el otro con amabilidad. Al final comprobaron la cuenta antes de pagar. Diego escribió para preguntar por el día. No todo salió bien, pero cada problema tenía una solución sencilla y pudieron seguir juntos.',[['salas','rooms/galleries'],['comprobaron','checked'],['salió bien','went well']], [q('¿Qué tienen en común las soluciones?','What do the solutions have in common?','Explican el problema concreto con amabilidad',['Cancelan toda la comida','No hablan con nadie'],'Specific polite requests solve both wrong food and missing coffee.'),q('¿Qué pidió Ana en lugar de la sopa?','What did Ana request instead of soup?','Una ensalada',['A salad','Salad'],'The soup contained chicken, so she chose salad.'),q('¿Por qué esperó dentro del museo?','Why did she wait inside the museum?','Hacía frío',['Luis no iba a venir','La estación estaba cerrada'],'Cold weather explains waiting inside, without implying cancellation.'),q('¿Qué hicieron antes de pagar?','What did they do before paying?','Comprobaron la cuenta',['Checked the bill','Check the bill'],'They verify the bill before payment.'),q('¿Qué mensaje resume su estrategia?','Which message summarises their strategy?','Tuvimos problemas, pero pedimos ayuda y seguimos el plan',['Todo fue perfecto y no pedimos nada','Nunca comimos juntos'],'It acknowledges problems and useful responses without claiming perfection.')]),
s('La chaqueta antes de volver','Después de comer, Marta quería cambiar una chaqueta. La compró el día anterior. Le quedaba pequeña y tenía el recibo. Ana y Luis fueron con ella a la tienda. La dependienta ofreció una mediana del mismo color, pero Marta prefirió probarla antes de aceptar. Le quedó bien. Mientras esperaba, Ana escribió a Diego: «Esta semana he ido al museo. Hoy hemos comido juntos y Marta ha cambiado su chaqueta». Luis miró la hora del tren. Todavía tenían tiempo, pero no querían perder otro transporte.',[['día anterior','previous day'],['ofreció','offered'],['le quedó bien','it fitted her']], [q('¿Por qué miró Luis la hora?','Why did Luis check the time?','No querían perder otro transporte',['La chaqueta costaba demasiado','No tenían ningún billete'],'The morning’s transport problem informs this practical check.'),q('¿Qué talla ofreció la dependienta?','Which size did the shop assistant offer?','La mediana',['Medium','The medium size'],'A medium in the same colour is the proposed replacement.'),q('¿Qué indica esta semana he ido?','What does esta semana he ido indicate?','Una experiencia dentro de la semana actual',['Un plan para la semana próxima','Una rutina de la infancia'],'The perfect recycles an open-period experience, distinct from the morning’s sequence.'),q('¿Qué hizo Marta antes de aceptar?','What did Marta do before accepting?','Se probó la chaqueta',['Tried on the jacket','She tried it on'],'Trying the replacement checks the solution before accepting.'),q('¿Qué frase une problema y solución?','Which statement links problem and solution?','La chaqueta era pequeña, así que pedí otra talla',['La chaqueta será pequeña ayer','La chaqueta era una estación'],'Description plus completed response links the service interaction.')]),
s('Un mensaje para Diego','Ana y Luis volvieron a Madrid por la tarde. El tren llegó a tiempo y pudieron sentarse juntos. Ana escribió a Diego: «Hacía frío y perdí el tren por la mañana. Después tomé el autobús y llegué al museo. Comimos con Marta y resolvimos dos problemas pequeños. Ahora estoy cansada, así que voy a descansar». Diego respondió que mañana podían tomar un café tranquilo. Ana aceptó, pero pidió quedar después de las diez. Diego entendió lo que pasó y el nuevo plan. Propuso quedar en el café del barrio, cerca de la casa de Ana.',[['resolvimos','we resolved'],['pudieron','they were able to'],['propuso','suggested']], [q('¿Qué hace útil el mensaje de Ana?','What makes Ana’s message useful?','Une fondo, hechos y el plan actual',['No dice cuándo pasó nada','Solo da una lista de verbos'],'The linked account explains the day and what happens next.'),q('¿Cómo se siente Ana ahora?','How does Ana feel now?','Cansada',['Tired','She is tired'],'Her current tiredness causes the rest plan.'),q('¿Qué hace Ana después de aceptar?','What does Ana do after accepting?','Pide quedar después de las diez',['Cancela el café de mañana','Propone otro tren hoy'],'She accepts and then asks to meet after ten; no reason for that exact time needs to be guessed.'),q('¿Qué tomó después de perder el tren?','What did she take after missing the train?','El autobús',['The bus','A bus'],'Después tomé el autobús gives the response to the morning problem.'),q('¿Qué respuesta mantiene el nuevo plan?','Which response keeps the new plan?','De acuerdo, mañana después de las diez',['Nos vemos ayer antes del tren','Ya no puedes usar pasado'],'It confirms the requested next-day arrangement.')])
]
];
